import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
N="تعليمات برنامج الدبلوم العالي"
F=[]
def r(c,a,q1,q2,q3): F.append(("rule",[1],c,a,q1,q2,q3))
r("المادة 1 و2","تسمى هذه التعليمات «تعليمات برنامج الدبلوم العالي في جامعة العلوم والتكنولوجيا الأردنية» ويعمل بها من تاريخ إقرارها من مجلس العمداء. والدبلوم العالي برنامج أكاديمي يكسب الطالب معلومات نظرية ومهارات تطبيقية عملية ومنهجية محددة في تخصص معين. والسنة الدراسية فصلان إجباريان مدة كل منهما ستة عشر أسبوعاً تشمل الامتحانات وفصل صيفي اختياري مدته ثمانية أسابيع.","ما تعريف الدبلوم العالي في تعليمات الجامعة؟","كم أسبوعاً مدة الفصل الدراسي والصيفي في الدبلوم العالي؟","شو هو الدبلوم العالي؟")
r("المادة 4","تقدم طلبات الالتحاق بالدبلوم العالي إلى عمادة كلية الدراسات العليا مباشرة حسب نموذج خاص، ولا يبت في أي طلب إلا إذا استوفى جميع الأوراق الثبوتية، ثم يحول إلى الكليات والأقسام للنظر والتنسيب بأسماء المرشحين حسب الشواغر إلى عمادة الدراسات العليا لإعلان القوائم وتحول إلى وحدة القبول والتسجيل للتنفيذ.","كيف تقدم طلبات الالتحاق بالدبلوم العالي؟","هل يبت في الطلب إذا نقصت الأوراق الثبوتية؟","وين بقدم طلب الدبلوم العالي؟")
r("المادة 5 (د-ز)","يشترط في قبول الدبلوم العالي أيضاً: أن تكون دراسة البكالوريوس بالانتظام وفي موضوع يؤهل للدراسة المتخصصة، وألا تكون صدرت بحقه عقوبة تأديبية لا تؤهله للقبول، وتحقيق الشروط التي تقترحها لجنة القسم وتقرها لجنة الكلية (ويجوز أن تشمل مساقات استدراكية بما لا يزيد عن 6 ساعات)، وألا يكون قد فصل من التخصص الذي سيتقدم إليه.","هل يشترط دراسة البكالوريوس بالانتظام للقبول في الدبلوم العالي؟","هل تمنع العقوبة التأديبية القبول في الدبلوم العالي؟","كم ساعة استدراكية بحد أقصى في الدبلوم العالي؟")
r("المادة 5 (التنافس)","إذا تجاوز عدد المتقدمين لبرنامج الدبلوم العالي العدد المقرر قبوله يجري القبول تنافسياً اعتماداً على أسس تضعها لجنة الكلية.","كيف يتم القبول في الدبلوم العالي إذا زاد عدد المتقدمين عن المقرر؟","من يضع أسس التنافس في الدبلوم العالي؟","إذا كثر المتقدمين على الدبلوم العالي، كيف بيختاروا؟")
r("المادة 6","يتم قبول الطالب في الدبلوم العالي بقرار من العميد بناءً على توصية من لجنة القسم وتنسيب من لجنة الكلية، ويبلغ العميد القرار إلى الطالب ومدير وحدة القبول والتسجيل والكلية. ولا يجوز قبول الطالب في برنامجين دراسيين أو أكثر في آن واحد في أي مرحلة من مراحل دراسته.","من يقرر قبول الطالب في الدبلوم العالي؟","هل يجوز الالتحاق ببرنامجين دراسيين في آن واحد؟","بقدر أدرس دبلوم عالي وماجستير بنفس الوقت؟")
r("المادة 7 (ب، ه)","يمدد الحد الأعلى لمدة الدبلوم العالي فصلاً دراسياً واحداً بقرار من العميد بناءً على توصية لجنة القسم وتنسيب لجنة الكلية، على أن يتم قبل نهاية الفصل الذي يسبق فصل التمديد. وإذا احتاج الطالب أقل من 6 ساعات في فصل تخرجه فله أن يسجل ما يحتاج إليه ضمن خطته.","من يقرر تمديد مدة الدبلوم العالي ومتى يطلب؟","هل يجوز تسجيل أقل من 6 ساعات في فصل التخرج في الدبلوم العالي؟","بقي علي 3 ساعات بس، بقدر أسجلهم؟")
r("المادة 8 (أ، ج، د)","يقبل تأجيل طالب الدبلوم العالي بقرار من العميد بناءً على توصية لجنة القسم وتنسيب لجنة الكلية. ولا تؤجل الدراسة في فصل التمديد، ولا يجوز لصاحب (غير مكتمل) تأجيل دراسته إلا بعد إزالتها ضمن الفترة المحددة. ولا تحتسب مدة التأجيل من الحد الأعلى لمدة الدراسة أو لغاية إزالة أسباب الوضع تحت المراقبة.","هل يجوز تأجيل الدراسة في فصل التمديد في الدبلوم العالي؟","هل أقدر أأجل وعندي غير مكتمل في الدبلوم العالي؟","مين بوافق على تأجيلي بالدبلوم العالي؟")
r("المادة 9 (أ)","إذا لم يسجل طالب منتظم لفصل دراسي ولم يحصل على موافقة خطية من العميد بتأجيل دراسته يفقد مقعده، وفي حال وجود عذر قهري يقبله العميد فله أن يطلب من مجلس الكلية اعتبار هذه المدة ضمن مدة التأجيل المسموح بها.","متى يفقد طالب الدبلوم العالي مقعده؟","هل يمكن اعتبار فصل عدم التسجيل ضمن مدة التأجيل؟","ما سجلت فصل ولا أخذت موافقة تأجيل، شو بصير؟")
r("المادة 9 (ب)","إذا رغب الطالب في الانسحاب من الجامعة فعليه التقدم بطلب على النموذج المعد إلى وحدة القبول والتسجيل، وتثبت ملاحظة (منسحب من الجامعة) في سجله ويفقد مقعده، ويبلغ العميد وعميد الكلية ورئيس القسم.","كيف ينسحب طالب الدبلوم العالي من الجامعة؟","ماذا يثبت في سجل الطالب المنسحب من الجامعة؟","بدي أنسحب من الدبلوم العالي، كيف؟")
r("المادة 9 (ج)","يجوز للطالب الذي فقد مقعده التقدم بطلب جديد للقبول، وفي حال قبوله يحتفظ بسجله الأكاديمي كاملاً ويكمل متطلبات التخرج وفق الخطة المعمول بها عند عودته، وتحسب مدة دراسته السابقة ضمن الحدين الأعلى والأدنى. وإذا اختلفت الخطة يحسم فصل دراسي واحد من الحد الأعلى لمدة الدراسة مقابل كل 6 ساعات معتمدة تحتسب للطالب.","ماذا يحدث لسجل طالب الدبلوم العالي إذا أعيد قبوله بعد فقدان المقعد؟","كم ساعة يحسم مقابلها فصل من الحد الأعلى إذا اختلفت الخطة؟","فقدت مقعدي وبدي أرجع، علاماتي بتضل؟")
r("المادة 10 (أ، ب)","يجوز انتقال الطالب من دبلوم عالي إلى آخر داخل الجامعة بقرار من المجلس بتوصية مجلس القسم المنتقل إليه وتنسيب لجنة الكلية، ويجوز معادلة بعض المساقات وإعفاؤه منها على أن تدخل في معدله التراكمي. وللمنتقل من جامعة أخرى يحسم من الحد الأعلى فصل دراسي واحد مقابل احتساب 6 ساعات معتمدة.","هل تدخل المساقات المعادلة داخل الجامعة في المعدل التراكمي في الدبلوم العالي؟","كم ساعة يحسم مقابلها فصل عند الانتقال من جامعة أخرى في الدبلوم العالي؟","انتقلت من دبلوم ثاني بالجامعة، علاماتي بتنحسب؟")
r("المادة 11","يجوز السماح للطالب بدراسة ما لا يزيد عن 3 ساعات معتمدة من برامج الدبلوم العالي في جامعة أردنية أو جامعات أخرى معترف بها بعد قبوله، بموافقة العميد بتنسيب لجنة الكلية وتوصية لجنة القسم، ويعفى منها بشرط ألا تقل علامته عن 75% ولا تدخل في معدله التراكمي، وألا يتجاوز مجموعها مع ساعات الانتقال 6 ساعات معتمدة.","كم ساعة يجوز دراستها من جامعة أخرى في الدبلوم العالي وما أقل علامة؟","ما أقصى مجموع للساعات المحتسبة من خارج الجامعة في الدبلوم العالي؟","بقدر أدرس مادة بجامعة ثانية وتنحسب لي؟")
r("المادة 12","يسمح بالإضافة والانسحاب من المساقات في الأسبوع الأول من الفصلين الأول والثاني وخلال الأيام الثلاثة الأولى من الصيفي ولا تثبت في السجل، على ألا يقل العبء عن 6 ساعات في الفصلين الأول أو الثاني. ويسمح بالانسحاب من مساق قبل بداية الامتحانات النهائية فيثبت بملاحظة (منسحب)، ولا يجوز الانسحاب من جميع المساقات إلا بعذر قهري يقبله العميد، فتكون دراسته مؤجلة، وإذا كان في الفصل الأول يعتبر منسحباً من الجامعة.","ماذا يحدث إذا انسحب طالب الدبلوم العالي من جميع المساقات في فصله الأول؟","ما الحد الأدنى للعبء الدراسي في الفصل الأول والثاني في الدبلوم العالي؟","متى بقدر أنسحب من مساق في الدبلوم العالي؟")
r("المادة 13 (أ، د، هـ)","يسجل مدرس المساق الحضور والغياب على كشوف خاصة ويسلمها لرئيس القسم نهاية كل فصل. وإذا غاب الطالب أكثر من 20% بعذر قهري أو مرضي يقبله عميد الكلية فللجنة الكلية اعتباره منسحباً من المساق ويبلغ عميد الكلية العميد ووحدة القبول والتسجيل خطياً قبل آخر موعد لتسليم النتائج. ويشترط في العذر المرضي شهادة من المركز الصحي في الجامعة أو معتمدة منه تقدم لعميد الكلية خلال أسبوعين من الانقطاع، وفي الحالات القاهرة الأخرى خلال أسبوعين من زوال الأسباب.","ماذا يحدث إذا غاب طالب الدبلوم العالي أكثر من 20% بعذر مقبول؟","خلال كم أسبوعاً تقدم الشهادة المرضية في الدبلوم العالي؟","مين بقرر انسحابي من المساق لو غبت بعذر مقبول؟")
r("المادة 14 (أ، ب)","تحسب العلامة النهائية لكل مساق في الدبلوم العالي من مئة لأقرب عدد صحيح. ويعقد الامتحان الأول خلال الأسبوعين السادس أو السابع من الفصل الأول أو الثاني والأسبوع الثالث من الفصل الصيفي، ويجوز أن يكون الامتحان الثاني شفوياً أو عملياً أو تقارير أو بحوثاً كلها أو بعضها حسب ما يراه مدرس المساق.","متى يعقد الامتحان الأول في الدبلوم العالي في الفصل الصيفي؟","هل يجوز أن يكون الامتحان الثاني شفوياً أو تقارير في الدبلوم العالي؟","أي أسبوع بكون أول امتحان بالدبلوم العالي؟")
r("المادة 14 (ج، د)","يعلن مدرس المساق نتائج الأعمال الفصلية قبل بدء الامتحانات النهائية بأسبوع على الأقل ويسلم نسخة لرئيس القسم. والعلامة النهائية هي مجموع الامتحان النهائي والأعمال الفصلية، وقد تكون الامتحانات بعضها أو كلها أعمالاً تطبيقية أو تقارير أو بحوثاً، ويحدد مجلس القسم كيفية إجراء الامتحانات وتوزيع العلامات في بداية كل فصل.","قبل كم يعلن المدرس نتائج الأعمال الفصلية في الدبلوم العالي؟","من يحدد كيفية الامتحانات وتوزيع العلامات في الدبلوم العالي؟","متى بتنزل علامات الأعمال الفصلية؟")
r("المادة 14 (هـ)","إذا تغيب الطالب عن الامتحان النهائي أو لم يستوف التقارير أو البحوث بعذر مرضي أو قهري يقبله عميد الكلية تسجل له (غير مكتمل) وعليه إزالتها خلال أسبوعين من بدء الفصل التالي الذي ينتظم فيه دون حساب الصيفي، وإلا تسجل له العلامة المستحقة من الأعمال الفصلية. وعند قبول العذر يعقد امتحان تكميلي مكافئ بالتنسيق خطياً مع رئيس القسم.","خلال كم أسبوعاً يجب إزالة (غير مكتمل) في الدبلوم العالي؟","هل يحسب الفصل الصيفي عند إزالة (غير مكتمل) في الدبلوم العالي؟","غبت عن النهائي بعذر، شو بصير بعلامتي؟")
r("المادة 15 (ج، د، و)","المعدل التراكمي هو معدل علامات جميع المساقات التي درسها الطالب نجاحاً أو رسوباً ضمن الخطة حتى تاريخ حسابه، وإذا حصل على (غير مكتمل) يحسب معدله عند اكتمال العلامات وبأثر رجعي من حيث المراقبة أو الفصل. والمعدل الفصلي معدل مساقات ذلك الفصل، وتحسب المعدلات لأقرب منزلة عشرية.","كيف يحسب المعدل التراكمي في الدبلوم العالي؟","إلى كم منزلة عشرية تحسب المعدلات في الدبلوم العالي؟","شو بصير بالمعدل لما يكون عندي غير مكتمل؟")
r("المادة 16 (ب)","على طالب الدبلوم العالي الموضوع تحت المراقبة إزالة الأسباب خلال فصل دراسي واحد دون الصيفي، تطرح خلاله المساقات التي رسب فيها، ويحسب هذا الفصل بعد الفصل الذي وضع بسبب نتائجه تحت المراقبة.","كم فصلاً يمهل الطالب لإزالة المراقبة في الدبلوم العالي؟","هل يحسب الفصل الصيفي لإزالة المراقبة في الدبلوم العالي؟","كيف بزيل المراقبة بالدبلوم العالي؟")
r("المادة 18","يفصل الطالب من الدبلوم العالي كذلك إذا لم يتمكن من إزالة الوضع تحت المراقبة، أو لم يتم المتطلبات ضمن الحد الأعلى لمدة الدراسة، أو انطبقت عليه المادة 5/ب (تقدير مقبول) ولم يحقق شروط التحول إلى طالب نظامي. وتصدر قرارات الفصل من مجلس العمداء بتنسيب من مدير وحدة القبول والتسجيل وتبلغ الطالب على آخر عنوان له.","من يصدر قرار الفصل في الدبلوم العالي؟","هل يفصل من لم يحقق شروط التحول إلى طالب نظامي؟","كيف بعرف إني انفصلت من الدبلوم العالي؟")
r("المادة 19 (ب)","يصنف تقدير الطالب في الدبلوم العالي بناءً على المعدل التراكمي: ممتاز من 88 إلى 100، وجيد جداً من 80 إلى أقل من 88، وجيد من 75 إلى أقل من 80.","كيف يصنف تقدير الدبلوم العالي؟","كم معدل الممتاز في الدبلوم العالي؟","شو بتكون الفئات بتقدير الدبلوم العالي؟")
r("المادة 20","يجوز أن تشمل الخطة الدراسية للطالب مساقات استدراكية يحددها القسم وينص عليها عند القبول، ولا تدخل في المعدل الفصلي والتراكمي ولا في متطلبات التخرج، شريطة أن ينهيها الطالب بنجاح في نهاية العام الجامعي الأول من التحاقه. ويحسب فصل دراسي إضافي لمن يطلب منه دراسة مساقات استدراكية 6 ساعات معتمدة.","هل تدخل المساقات الاستدراكية في معدل الدبلوم العالي ومتى ينهيها الطالب؟","كم ساعة استدراكية يحسب مقابلها فصل إضافي في الدبلوم العالي؟","بدخل المساق الاستدراكي بالمعدل؟")
r("المادة 21-23","تتولى لجنة الدراسات العليا في الكلية التنسيق بين الأقسام المختلفة فيما يتعلق ببرنامج الدبلوم العالي وأية أمور يفوضها بها المجلس. ويبت مجلس العمداء في الإشكاليات الناشئة عن تطبيق التعليمات، ورئيس الجامعة والعميد وعمداء الكليات ومدير وحدة القبول والتسجيل مسؤولون عن تطبيقها.","ما صلاحيات لجنة الدراسات العليا في الكلية في الدبلوم العالي؟","من يبت في الإشكاليات الناشئة عن تطبيق تعليمات الدبلوم العالي؟","من المسؤول عن تطبيق تعليمات الدبلوم العالي؟")
